-- Additive domain migration. Existing article IDs and profile JSON remain authoritative.
CREATE TABLE IF NOT EXISTS companies (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, blog_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), mode TEXT NOT NULL CHECK(mode IN ('feed','listing','manual')), blog_url TEXT NOT NULL, feed_urls TEXT NOT NULL, include_url_regex TEXT, exclude_url_regex TEXT);
CREATE INDEX IF NOT EXISTS sources_company_idx ON sources(company_id);
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL UNIQUE, parent_id TEXT REFERENCES topics(id));
CREATE TABLE IF NOT EXISTS topic_keywords (topic_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE, term TEXT NOT NULL, weight REAL NOT NULL DEFAULT 1, PRIMARY KEY(topic_id,term));
CREATE TABLE IF NOT EXISTS article_topics (article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, topic_id TEXT NOT NULL REFERENCES topics(id), score REAL NOT NULL DEFAULT 1, PRIMARY KEY(article_id,topic_id));
CREATE INDEX IF NOT EXISTS article_topics_topic_idx ON article_topics(topic_id,article_id);
CREATE INDEX IF NOT EXISTS articles_time_idx ON articles(COALESCE(published_at,discovered_at) DESC,id DESC);
CREATE TABLE IF NOT EXISTS user_company_follows (user_id TEXT NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE, company_id TEXT NOT NULL REFERENCES companies(id), PRIMARY KEY(user_id,company_id));
CREATE TABLE IF NOT EXISTS user_topic_follows (user_id TEXT NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE, topic_id TEXT NOT NULL REFERENCES topics(id), PRIMARY KEY(user_id,topic_id));
CREATE TABLE IF NOT EXISTS user_bookmarks (user_id TEXT NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE, article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS user_read_logs (user_id TEXT NOT NULL REFERENCES profiles(user_id) ON DELETE CASCADE, article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, read_at TEXT NOT NULL, PRIMARY KEY(user_id,article_id));
CREATE INDEX IF NOT EXISTS user_read_logs_date_idx ON user_read_logs(user_id,read_at DESC);
CREATE TABLE IF NOT EXISTS engagements (reader_id TEXT NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('read','save')), active INTEGER NOT NULL CHECK(active IN (0,1)), occurred_at TEXT NOT NULL, PRIMARY KEY(reader_id,article_id,kind));
CREATE INDEX IF NOT EXISTS engagements_recent_idx ON engagements(active,occurred_at,article_id);
CREATE INDEX IF NOT EXISTS engagements_reader_idx ON engagements(reader_id,occurred_at);
CREATE TABLE IF NOT EXISTS app_state (id TEXT PRIMARY KEY NOT NULL, value INTEGER NOT NULL);
INSERT OR IGNORE INTO app_state VALUES ('content_revision',1),('engagement_revision',1);
CREATE TABLE IF NOT EXISTS feed_sessions (id TEXT PRIMARY KEY NOT NULL, owner_hash TEXT NOT NULL, request_hash TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, total INTEGER NOT NULL DEFAULT 0, basis TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS feed_sessions_cache_idx ON feed_sessions(owner_hash,request_hash,expires_at);
CREATE INDEX IF NOT EXISTS feed_sessions_expiry_idx ON feed_sessions(expires_at);
CREATE TABLE IF NOT EXISTS feed_chunks (session_id TEXT NOT NULL REFERENCES feed_sessions(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL, ids TEXT NOT NULL, basis TEXT NOT NULL, PRIMARY KEY(session_id,chunk_index));
CREATE TABLE IF NOT EXISTS readzz_migrations (name TEXT PRIMARY KEY NOT NULL, applied_at TEXT NOT NULL);

-- Compatibility projections are transactional with the original row write.
CREATE TRIGGER IF NOT EXISTS readzz_article_insert AFTER INSERT ON articles BEGIN
  INSERT OR IGNORE INTO article_topics(article_id,topic_id) SELECT NEW.id,t.id FROM json_each(CASE WHEN json_valid(NEW.topics) THEN NEW.topics ELSE '[]' END) j JOIN topics t ON t.name=j.value OR t.id=j.value;
  UPDATE app_state SET value=value+1 WHERE id='content_revision';
END;
CREATE TRIGGER IF NOT EXISTS readzz_article_update AFTER UPDATE OF title,summary,published_at,topics ON articles BEGIN
  DELETE FROM article_topics WHERE article_id=NEW.id;
  INSERT OR IGNORE INTO article_topics(article_id,topic_id) SELECT NEW.id,t.id FROM json_each(CASE WHEN json_valid(NEW.topics) THEN NEW.topics ELSE '[]' END) j JOIN topics t ON t.name=j.value OR t.id=j.value;
  UPDATE app_state SET value=value+1 WHERE id='content_revision';
END;
CREATE TRIGGER IF NOT EXISTS readzz_company_insert BEFORE INSERT ON articles BEGIN
  SELECT RAISE(ABORT,'Unknown article company') WHERE NOT EXISTS (SELECT 1 FROM companies WHERE id=NEW.company_id);
END;
CREATE TRIGGER IF NOT EXISTS readzz_company_update BEFORE UPDATE OF company_id ON articles BEGIN
  SELECT RAISE(ABORT,'Unknown article company') WHERE NOT EXISTS (SELECT 1 FROM companies WHERE id=NEW.company_id);
END;
CREATE TRIGGER IF NOT EXISTS readzz_engagement_insert AFTER INSERT ON engagements BEGIN
  UPDATE app_state SET value=value+1 WHERE id='engagement_revision';
END;
CREATE TRIGGER IF NOT EXISTS readzz_engagement_update AFTER UPDATE OF active ON engagements WHEN OLD.active<>NEW.active BEGIN
  UPDATE app_state SET value=value+1 WHERE id='engagement_revision';
END;

